,"name":"Marketing and Business Development","parent":"630000","type":"Expense","normal":"Debit","kind":"Posting"},{"code":"632001","name":"Bank Charges","parent":"630000","type":"Expense","normal":"Debit","kind":"Posting"},{"code":"633000","name":"Depreciation expenses","parent":"630000","type":"Expense","normal":"Debit","kind":"Group"},{"code":"633001","name":"Depreciation — Computers and Equipment","parent":"633000","type":"Expense","normal":"Debit","kind":"Posting"},{"code":"633002","name":"Depreciation — Furniture and Fixtures","parent":"633000","type":"Expense","normal":"Debit","kind":"Posting"},{"code":"633003","name":"Depreciation — Vehicles","parent":"633000","type":"Expense","normal":"Debit","kind":"Posting"},{"code":"633004","name":"Depreciation — Leasehold Improvements","parent":"633000","type":"Expense","normal":"Debit","kind":"Posting"},{"code":"634001","name":"Credit Loss Expense","parent":"630000","type":"Expense","normal":"Debit","kind":"Posting"},{"code":"700000","name":"Other income and expenses","parent":null,"type":"Expense","normal":"Debit","kind":"Group"},{"code":"710000","name":"Other income","parent":"700000","type":"Revenue","normal":"Credit","kind":"Group"},{"code":"711001","name":"Interest Income","parent":"710000","type":"Revenue","normal":"Credit","kind":"Posting"},{"code":"712001","name":"Realized Foreign Exchange Gains","parent":"710000","type":"Revenue","normal":"Credit","kind":"Posting"},{"code":"713001","name":"Unrealized Foreign Exchange Gains","parent":"710000","type":"Revenue","normal":"Credit","kind":"Posting"},{"code":"720000","name":"Other expenses","parent":"700000","type":"Expense","normal":"Debit","kind":"Group"},{"code":"721001","name":"Interest Expense","parent":"720000","type":"Expense","normal":"Debit","kind":"Posting"},{"code":"722001","name":"Realized Foreign Exchange Losses","parent":"720000","type":"Expense","normal":"Debit","kind":"Posting"},{"code":"723001","name":"Unrealized Foreign Exchange Losses","parent":"72